(function () {
  var root = document.querySelector('.fx'); if (!root) return;
  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  var INK = [26, 26, 24], BLUE = [37, 99, 235];
  // Targets per state. The bubble holds in a little while an agent works, then springs out when the reply lands.
  var T = {
    waiting: { scale: 1, blue: 0, green: 0, amp: 0, dots: 1, kick: 0 },
    working: { scale: 0.92, blue: 0, green: 0, amp: 1, dots: 1, kick: 0 },
    replied: { scale: 1, blue: 1, green: 0, amp: 0, dots: 1, kick: 2.2 },
    resolved: { scale: 1, blue: 0, green: 1, amp: 0, dots: 0, kick: 1.2 }
  };
  // Springs keep their velocity when the target changes, so any state change mid-morph carries on smoothly.
  var K = { scale: [380, 18], blue: [260, 32], green: [260, 32], amp: [200, 22], dots: [300, 34] };
  var pins = [].map.call(root.querySelectorAll('.fx-pin'), function (svg) {
    var v = {}; for (var k in K) v[k] = [T.waiting[k], 0];
    return { ink: svg.dataset.kind === 'ink', body: svg.querySelector('.fx-body'),
      blue: svg.querySelector('[data-layer="blue"]'), green: svg.querySelector('[data-layer="green"]'),
      lines: svg.querySelectorAll('.fx-line'), dots: svg.querySelectorAll('.fx-dot'), v: v, state: 'waiting' };
  });
  var buttons = root.querySelectorAll('.fx-seg button');
  function set(state) {
    pins.forEach(function (p) {
      if (p.state === state) return;
      p.state = state;
      if (!reduce) p.v.scale[1] += T[state].kick;
      var f = state === 'working' ? 'url(#fi-boil)' : 'url(#fi-wob)';
      [].forEach.call(p.lines, function (l) { l.setAttribute('filter', f); });
    });
    [].forEach.call(buttons, function (b) { b.setAttribute('aria-pressed', String(b.dataset.state === state)); });
  }
  function clamp(x) { return Math.max(0, Math.min(1, x)); }
  function mix(a, b, t) { return 'rgb(' + a.map(function (x, i) { return Math.round(x + (b[i] - x) * t); }).join(',') + ')'; }
  var last = performance.now();
  function tick(now) {
    var dt = Math.min(0.032, (now - last) / 1000); last = now;
    var t = now / 1000;
    pins.forEach(function (p) {
      var tg = T[p.state];
      for (var k in K) {
        var s = p.v[k];
        if (reduce && k === 'amp') { s[0] = 0; continue; }
        var target = reduce && k === 'scale' ? 1 : tg[k];
        var a = -K[k][0] * (s[0] - target) - K[k][1] * s[1];
        s[1] += a * dt; s[0] += s[1] * dt;
      }
      var v = p.v;
      p.body.setAttribute('transform', 'translate(3 34) scale(' + v.scale[0].toFixed(4) + ') translate(-3 -34)');
      p.blue.setAttribute('opacity', clamp(v.blue[0]).toFixed(3));
      p.green.setAttribute('opacity', clamp(v.green[0]).toFixed(3));
      var amp = Math.max(0, v.amp[0]), shown = clamp(v.dots[0]);
      var color = p.ink ? '#fff' : mix(INK, BLUE, clamp(v.blue[0]));
      [].forEach.call(p.dots, function (d, i) {
        var w = Math.max(0, Math.sin(t * 5.2 - i * 0.9));
        d.setAttribute('transform', 'translate(0 ' + (-1.6 * amp * w).toFixed(3) + ')');
        d.setAttribute('opacity', (shown * (1 - 0.5 * amp * (1 - w))).toFixed(3));
        d.setAttribute('r', (2 * (0.6 + 0.4 * shown)).toFixed(3));
        d.setAttribute('fill', color);
      });
    });
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
  // Starts still on Waiting. Play loop walks the states; picking a state stops it.
  var order = [['waiting', 1200], ['working', 2400], ['replied', 1800], ['resolved', 1400]], i = 0, timer = null;
  function step() { set(order[i][0]); timer = setTimeout(function () { i = (i + 1) % order.length; step(); }, order[i][1]); }
  function stop() { clearTimeout(timer); timer = null; }
  [].forEach.call(buttons, function (b) { b.addEventListener('click', function () { stop(); set(b.dataset.state); }); });
  var play = root.querySelector('.fx-play');
  if (play) play.addEventListener('click', function () { stop(); i = 0; step(); });
})();

