.fx .fx-bar { display: flex; align-items: center; gap: 12px; }
.fx .fx-seg { display: inline-flex; padding: 4px; gap: 4px; border-radius: 8px; background: #e9e8e3; }
.fx .fx-seg button, .fx .fx-play { height: 28px; padding: 0 12px; border: 0; border-radius: 6px; background: transparent; font: 500 12px ui-sans-serif, system-ui, sans-serif; color: #6b6a64; cursor: pointer; }
.fx .fx-seg button[aria-pressed="true"] { background: #fff; color: #1a1a18; box-shadow: 0 1px 2px rgba(26,26,24,.16); }
.fx .fx-play { background: #fff; color: #1a1a18; box-shadow: 0 0 0 1px #e2e0d8; }
.fx .fx-stages { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.fx .fx-stage { height: 200px; border-radius: 8px; background: #e9e8e3; display: flex; align-items: center; justify-content: center; position: relative; }
.fx .fx-stage .fi-cap { position: absolute; left: 12px; top: 12px; }
.fx .fx-strip { display: grid; grid-template-columns: repeat(7, 1fr); gap: 8px; }
.fx .fx-frame { display: flex; flex-direction: column; gap: 8px; }
.fx .fx-fstage { height: 104px; border-radius: 8px; background: #e9e8e3; display: flex; align-items: center; justify-content: center; }

document.querySelectorAll('.pop').forEach(function (pop) {
  var txt = pop.querySelector('.txt');
  var failed = pop.querySelector('.failed');
  var send = pop.querySelector('.send');
  function clear() { pop.classList.remove('err'); }
  txt.addEventListener('input', clear);
  txt.addEventListener('keydown', function (e) {
    if (e.key.length === 1 || e.key === 'Backspace' || e.key === 'Delete') clear();
  });
  failed.addEventListener('click', function () { clear(); txt.focus(); });
  send.addEventListener('click', function () { pop.classList.add('err'); });
});

(function () {
  // Only a working agent's pin moves: its line redraws like boiling ink.
  var n = document.getElementById('ct-boil-noise'); if (!n) return;
  if (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var s = 1;
  setInterval(function () { s = s % 4 + 1; n.setAttribute('seed', String(s)); }, 120);
})();
